import{_ as o,a0 as p,w as d,s as h,I as n,x as e,a1 as i,A as t,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"重啓和關閉 Linux 系統的 6 個終端命令 | LCTT x X-CMD","titleTemplate":false,"description":"重啓和關閉 Linux 系統的 6 個終端命令 | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"重啓和關閉 Linux 系統的 6 個終端命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"重啓和關閉 Linux 系統的 6 個終端命令 | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20181009 6 Commands To Shutdown And Reboot The Linux System From Terminal","title":"重啓和關閉 Linux 系統的 6 個終端命令","tag":"201810","desc":""},"relativePath":"201810/20181009 6 Commands To Shutdown And Reboot The Linux System From Terminal.md","filePath":"[post].md"}'),r={name:"201810/20181009 6 Commands To Shutdown And Reboot The Linux System From Terminal.md"};function c(u,s,g,k,b,f){const a=p("Link");return d(),h("div",null,[s[19]||(s[19]=n("h1",{id:"重啓和關閉-linux-系統的-6-個終端命令",tabindex:"-1"},[e("重啓和關閉 Linux 系統的 6 個終端命令 "),n("a",{class:"header-anchor",href:"#重啓和關閉-linux-系統的-6-個終端命令","aria-label":"Permalink to “重啓和關閉 Linux 系統的 6 個終端命令”"},"​")],-1)),s[20]||(s[20]=n("p",null,"在 Linux 管理員的日程當中，有很多需要執行的任務，其中就有系統的重啓和關閉。",-1)),s[21]||(s[21]=n("p",null,"對於 Linux 管理員來説，重啓和關閉系統是其諸多風險操作中的一例，有時候，由於某些原因，這些操作可能無法挽回，他們需要更多的時間來排查問題。",-1)),s[22]||(s[22]=n("p",null,"在 Linux 命令列模式下我們可以執行這些任務。很多時候，由於熟悉命令列，Linux 管理員更傾向於在命令列下完成這些任務。",-1)),s[23]||(s[23]=n("p",null,"重啓和關閉系統的 Linux 命令並不多，用户需要根據需要，選擇合適的命令來完成任務。",-1)),s[24]||(s[24]=n("p",null,"以下所有命令都有其自身特點，並允許被 Linux 管理員使用.",-1)),s[25]||(s[25]=n("p",null,[n("strong",null,"建議閲讀：")],-1)),n("ul",null,[n("li",null,[i(a,{href:"https://www.2daygeek.com/11-methods-to-find-check-system-server-uptime-in-linux/"},{default:t(()=>[...s[0]||(s[0]=[e("查看系統/服務器正常運行時間的 11 個方法",-1)])]),_:1})]),n("li",null,[i(a,{href:"https://www.2daygeek.com/tuptime-a-tool-to-report-the-historical-and-statistical-running-time-of-linux-system/"},{default:t(()=>[...s[1]||(s[1]=[e("Tuptime 一款為 Linux 系統保存歷史記錄、統計運行時間工具",-1)])]),_:1})])]),s[26]||(s[26]=l(`<p>系統重啓和關閉之始，會通知所有已登錄的用户和進程。當然，如果使用了時間參數，系統將拒絕新的用户登入。</p><p>執行此類操作之前，我建議您堅持複查，因為您只能得到很少的提示來確保這一切順利。</p><p>下面陳列了一些步驟：</p><ul><li>確保您擁有一個可以處理故障的控制台，以防之後可能會發生的問題。 VMWare 可以訪問虛擬機，而 IPMI、iLO 和 iDRAC 可以訪問物理服務器。</li><li>您需要通過公司的流程，申請修改或故障的執行權直到得到許可。</li><li>為安全着想，備份重要的配置文件，並保存到其他服務器上.</li><li>驗證日誌文件（提前檢查）</li><li>和相關團隊交流，比如資料庫管理團隊，應用團隊等。</li><li>通知資料庫和應用服務人員關閉服務，並得到確定答覆。</li><li>使用適當的命令覆盤操作，驗證工作。</li><li>最後，重啓系統。</li><li>驗證日誌文件，如果一切順利，執行下一步操作，如果發現任何問題，對症排查。</li><li>無論是回退版本還是運行程序，通知相關團隊提出申請。</li><li>對操作做適當守候，並將預期的一切正常的反饋給團隊</li></ul><p>使用下列命令執行這項任務。</p><ul><li><code>shutdown</code>、<code>halt</code>、<code>poweroff</code>、<code>reboot</code> 命令：用來停機、重啓或切斷電源</li><li><code>init</code> 命令：是 “initialization” 的簡稱，是系統啓動的第一個進程。</li><li><code>systemctl</code> 命令：systemd 是 Linux 系統和服務器的管理程序。</li></ul><h3 id="方案-1-如何使用-shutdown-命令關閉和重啓-linux-系統" tabindex="-1">方案 1：如何使用 shutdown 命令關閉和重啓 Linux 系統 <a class="header-anchor" href="#方案-1-如何使用-shutdown-命令關閉和重啓-linux-系統" aria-label="Permalink to “方案 1：如何使用 shutdown 命令關閉和重啓 Linux 系統”">​</a></h3><p><code>shutdown</code> 命令用於斷電或重啓本地和遠程的 Linux 機器。它為高效完成作業提供多個選項。如果使用了時間參數，系統關閉的 5 分鐘之前，會創建 <code>/run/nologin</code> 文件，以確保後續的登錄會被拒絕。</p><p>通用語法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># shutdown [OPTION] [TIME] [MESSAGE]</span></span></code></pre></div><p>運行下面的命令來立即關閉 Linux 機器。它會立刻殺死所有進程，並關閉系統。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># shutdown -h now</span></span></code></pre></div><ul><li><code>-h</code>：如果不特指 <code>-halt</code> 選項，這等價於 <code>-poweroff</code> 選項。</li></ul><p>另外我們可以使用帶有 <code>-halt</code> 選項的 <code>shutdown</code> 命令來立即關閉設備。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># shutdown --halt now</span></span>
<span class="line"><span>或者</span></span>
<span class="line"><span># shutdown -H now</span></span></code></pre></div><ul><li><code>-H, --halt</code>：停止設備運行</li></ul><p>另外我們可以使用帶有 <code>poweroff</code> 選項的 <code>shutdown</code> 命令來立即關閉設備。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># shutdown --poweroff now</span></span>
<span class="line"><span>或者</span></span>
<span class="line"><span># shutdown -P now</span></span></code></pre></div><ul><li><code>-P, --poweroff</code>：切斷電源（默認）。</li></ul><p>如果您沒有使用時間選項運行下面的命令，它將會在一分鐘後執行給出的命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># shutdown -h</span></span>
<span class="line"><span>Shutdown scheduled for Mon 2018-10-08 06:42:31 EDT, use &#39;shutdown -c&#39; to cancel.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>root@2daygeek.com#</span></span>
<span class="line"><span>Broadcast message from root@vps.2daygeek.com (Mon 2018-10-08 06:41:31 EDT):</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The system is going down for power-off at Mon 2018-10-08 06:42:31 EDT!</span></span></code></pre></div><p>其他的登錄用户都能在中斷中看到如下的廣播消息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[daygeek@2daygeek.com ~]$</span></span>
<span class="line"><span>Broadcast message from root@2daygeek.com (Mon 2018-10-08 06:41:31 EDT):</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The system is going down for power-off at Mon 2018-10-08 06:42:31 EDT!</span></span></code></pre></div><p>對於使用了 <code>-halt</code> 選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># shutdown -H</span></span>
<span class="line"><span>Shutdown scheduled for Mon 2018-10-08 06:37:53 EDT, use &#39;shutdown -c&#39; to cancel.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>root@2daygeek.com#</span></span>
<span class="line"><span>Broadcast message from root@vps.2daygeek.com (Mon 2018-10-08 06:36:53 EDT):</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The system is going down for system halt at Mon 2018-10-08 06:37:53 EDT!</span></span></code></pre></div><p>對於使用了 <code>-poweroff</code> 選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># shutdown -P</span></span>
<span class="line"><span>Shutdown scheduled for Mon 2018-10-08 06:40:07 EDT, use &#39;shutdown -c&#39; to cancel.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>root@2daygeek.com#</span></span>
<span class="line"><span>Broadcast message from root@vps.2daygeek.com (Mon 2018-10-08 06:39:07 EDT):</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The system is going down for power-off at Mon 2018-10-08 06:40:07 EDT!</span></span></code></pre></div><p>可以在您的終端上敲擊 <code>shutdown -c</code> 選項取消操作。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># shutdown -c</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Broadcast message from root@vps.2daygeek.com (Mon 2018-10-08 06:39:09 EDT):</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The system shutdown has been cancelled at Mon 2018-10-08 06:40:09 EDT!</span></span></code></pre></div><p>其他的登錄用户都能在中斷中看到如下的廣播消息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[daygeek@2daygeek.com ~]$</span></span>
<span class="line"><span>Broadcast message from root@vps.2daygeek.com (Mon 2018-10-08 06:41:35 EDT):</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The system shutdown has been cancelled at Mon 2018-10-08 06:42:35 EDT!</span></span></code></pre></div><p>添加時間參數，如果你想在 <code>N</code> 秒之後執行關閉或重啓操作。這裏，您可以為所有登錄用户添加自定義廣播消息。例如，我們將在五分鐘後重啓設備。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># shutdown -r +5 &quot;To activate the latest Kernel&quot;</span></span>
<span class="line"><span>Shutdown scheduled for Mon 2018-10-08 07:13:16 EDT, use &#39;shutdown -c&#39; to cancel.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[root@vps138235 ~]#</span></span>
<span class="line"><span>Broadcast message from root@vps.2daygeek.com (Mon 2018-10-08 07:08:16 EDT):</span></span>
<span class="line"><span></span></span>
<span class="line"><span>To activate the latest Kernel</span></span>
<span class="line"><span>The system is going down for reboot at Mon 2018-10-08 07:13:16 EDT!</span></span></code></pre></div><p>運行下面的命令立即重啓 Linux 機器。它會立即殺死所有進程並且重新啓動系統。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># shutdown -r now</span></span></code></pre></div><ul><li><code>-r, --reboot</code>： 重啓設備。</li></ul><h3 id="方案-2-如何通過-reboot-命令關閉和重啓-linux-系統" tabindex="-1">方案 2：如何通過 reboot 命令關閉和重啓 Linux 系統 <a class="header-anchor" href="#方案-2-如何通過-reboot-命令關閉和重啓-linux-系統" aria-label="Permalink to “方案 2：如何通過 reboot 命令關閉和重啓 Linux 系統”">​</a></h3><p><code>reboot</code> 命令用於關閉和重啓本地或遠程設備。<code>reboot</code> 命令擁有兩個實用的選項。</p><p>它能夠優雅的關閉和重啓設備（就好像在系統菜單中惦記重啓選項一樣簡單）。</p><p>執行不帶任何參數的 <code>reboot</code> 命令來重啓 Linux 機器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># reboot</span></span></code></pre></div><p>執行帶 <code>-p</code> 參數的 <code>reboot</code> 命令來關閉 Linux 機器電源。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># reboot -p</span></span></code></pre></div><ul><li><code>-p, --poweroff</code>：調用 <code>halt</code> 或 <code>poweroff</code> 命令，切斷設備電源。</li></ul><p>執行帶 <code>-f</code> 參數的 <code>reboot</code> 命令來強制重啓 Linux 設備（這類似按壓機器上的電源鍵）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># reboot -f</span></span></code></pre></div><ul><li><code>-f, --force</code>：立刻強制中斷，切斷電源或重啓。</li></ul><h3 id="方案-3-如何通過-init-命令關閉和重啓-linux-系統" tabindex="-1">方案 3：如何通過 init 命令關閉和重啓 Linux 系統 <a class="header-anchor" href="#方案-3-如何通過-init-命令關閉和重啓-linux-系統" aria-label="Permalink to “方案 3：如何通過 init 命令關閉和重啓 Linux 系統”">​</a></h3><p><code>init</code>（“initialization” 的簡寫）是系統啓動的第一個進程。</p><p>它將會檢查 <code>/etc/inittab</code> 文件並決定 linux 運行級別。同時，允許用户在 Linux 設備上執行關機或重啓操作. 這裏存在從 <code>0</code> 到 <code>6</code> 的七個運行等級。</p><p><strong>建議閲讀：</strong></p>`,51)),n("ul",null,[n("li",null,[i(a,{href:"https://www.2daygeek.com/how-to-check-all-running-services-in-linux/"},{default:t(()=>[...s[2]||(s[2]=[e("如何檢查 Linux 上所有運行的服務",-1)])]),_:1})])]),s[27]||(s[27]=l('<p>執行以下 <code>init</code> 命令關閉系統。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># init 0</span></span></code></pre></div><ul><li><code>0</code>： 停機 – 關閉系統。</li></ul><p>運行下面的 <code>init</code> 命令重啓設備：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># init 6</span></span></code></pre></div><ul><li><code>6</code>：重啓 – 重啓設備。</li></ul><h3 id="方案-4-如何通過-halt-命令關閉和重啓-linux-系統" tabindex="-1">方案 4：如何通過 halt 命令關閉和重啓 Linux 系統 <a class="header-anchor" href="#方案-4-如何通過-halt-命令關閉和重啓-linux-系統" aria-label="Permalink to “方案 4：如何通過 halt 命令關閉和重啓 Linux 系統”">​</a></h3><p><code>halt</code> 命令用來切斷電源或關閉遠程 Linux 機器或本地主機。 中斷所有進程並關閉 cpu。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># halt</span></span></code></pre></div><h3 id="方案-5-如何通過-poweroff-命令關閉和重啓-linux-系統" tabindex="-1">方案 5：如何通過 poweroff 命令關閉和重啓 Linux 系統 <a class="header-anchor" href="#方案-5-如何通過-poweroff-命令關閉和重啓-linux-系統" aria-label="Permalink to “方案 5：如何通過 poweroff 命令關閉和重啓 Linux 系統”">​</a></h3><p><code>poweroff</code> 命令用來切斷電源或關閉遠程 Linux 機器或本地主機。 <code>poweroff</code> 很像 <code>halt</code>，但是它可以關閉設備硬件（燈和其他 PC 上的其它東西）。它會給主板發送 ACPI 指令，然後信號發送到電源，切斷電源。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># poweroff</span></span></code></pre></div><h3 id="方案-6-如何通過-systemctl-命令關閉和重啓-linux-系統" tabindex="-1">方案 6：如何通過 systemctl 命令關閉和重啓 Linux 系統 <a class="header-anchor" href="#方案-6-如何通過-systemctl-命令關閉和重啓-linux-系統" aria-label="Permalink to “方案 6：如何通過 systemctl 命令關閉和重啓 Linux 系統”">​</a></h3><p>systemd 是一款適用於所有主流 Linux 髮型版的全新 init 系統和系統管理器，而不是傳統的 SysV init 系統。</p><p>systemd 兼容與 SysV 和 LSB 初始化腳本。它能夠替代 SysV init 系統。systemd 是內核啓動的第一個進程，並持有序號為 1 的進程 PID。</p><p><strong>建議閲讀：</strong></p>',16)),n("ul",null,[n("li",null,[i(a,{href:"https://www.2daygeek.com/chkservice-a-tool-for-managing-systemd-units-from-linux-terminal/"},{default:t(()=>[...s[3]||(s[3]=[e("chkservice – 一款終端下系統單元管理工具",-1)])]),_:1})])]),s[28]||(s[28]=l(`<p>它是一切進程的父進程，Fedora 15 是第一個適配安裝 systemd （替代了 upstart）的發行版。</p><p><code>systemctl</code> 是命令列下管理 systemd 守護進程和服務的主要工具（如 <code>start</code>、<code>restart</code>、<code>stop</code>、<code>enable</code>、<code>disable</code>、<code>reload</code> &amp; <code>status</code>）。</p><p>systemd 使用 .service 文件而不是 SysV init 使用的 bash 腳本。 systemd 將所有守護進程歸與自身的 Linux cgroups 用户組下，您可以瀏覽 <code>/cgroup/systemd</code> 文件查看該系統層次等級。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl halt</span></span>
<span class="line"><span># systemctl poweroff</span></span>
<span class="line"><span># systemctl reboot</span></span>
<span class="line"><span># systemctl suspend</span></span>
<span class="line"><span># systemctl hibernate</span></span></code></pre></div><hr>`,5)),n("p",null,[s[5]||(s[5]=e("via: ",-1)),i(a,{href:"https://www.2daygeek.com/6-commands-to-shutdown-halt-poweroff-reboot-the-linux-system/"},{default:t(()=>[...s[4]||(s[4]=[e("https://www.2daygeek.com/6-commands-to-shutdown-halt-poweroff-reboot-the-linux-system/",-1)])]),_:1})]),n("p",null,[s[10]||(s[10]=e("作者：",-1)),i(a,{href:"https://www.2daygeek.com/author/prakash/"},{default:t(()=>[...s[6]||(s[6]=[e("Prakash Subramanian",-1)])]),_:1}),s[11]||(s[11]=e(" 選題：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[7]||(s[7]=[e("lujun9972",-1)])]),_:1}),s[12]||(s[12]=e(" 譯者：",-1)),i(a,{href:"https://github.com/cyleft"},{default:t(()=>[...s[8]||(s[8]=[e("cyleft",-1)])]),_:1}),s[13]||(s[13]=e(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[9]||(s[9]=[e("wxy",-1)])]),_:1})]),n("p",null,[s[16]||(s[16]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[14]||(s[14]=[e("LCTT",-1)])]),_:1}),s[17]||(s[17]=e(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:t(()=>[...s[15]||(s[15]=[e("Linux中國",-1)])]),_:1}),s[18]||(s[18]=e(" 榮譽推出",-1))])])}const w=o(r,[["render",c]]);export{x as __pageData,w as default};
